from datetime import timedelta


def _is_workday(day, holidays):
    return day.weekday() < 5 and day not in holidays


def add_workdays(start, days, holidays=()):
    """The date `days` working days from `start`. See TASK.md."""
    if isinstance(days, bool) or not isinstance(days, int):
        raise TypeError("days must be an int")

    holiday_set = set(holidays)
    if days == 0:
        result = start
        while not _is_workday(result, holiday_set):
            result += timedelta(days=1)
        return result

    step = 1 if days > 0 else -1
    remaining = abs(days)
    result = start
    while remaining:
        result += timedelta(days=step)
        if _is_workday(result, holiday_set):
            remaining -= 1
    return result


def count_workdays(first, last, holidays=()):
    """Working days from `first` to `last`, both included. See TASK.md."""
    if first > last:
        return -count_workdays(last, first, holidays)

    holiday_set = set(holidays)
    result = 0
    current = first
    while current <= last:
        if _is_workday(current, holiday_set):
            result += 1
        current += timedelta(days=1)
    return result
